    # create a hash map to store the indices of each character in the inorder traversal
    inorder_map = {}
    for i, char in enumerate(inorder):
        inorder_map[char] = i

    # create a hash map to store the indices of each character in the postorder traversal
    postorder_map = {}
    for i, char in enumerate(postorder):
        postorder_map[char] = i

    # create a stack to store the indices of the nodes in the postorder traversal
    postorder_stack = []
    for i in range(len(postorder)):
        postorder_stack.append(i)

    # create a string to store the preorder traversal
    preorder = ""

    # while the stack is not empty
    while postorder_stack:
        # pop the top node from the stack
        node = postorder_stack.pop()

        # add the character corresponding to the node to the preorder string
        preorder += inorder[node]

        # if the left child is not None
        if inorder_map[inorder[node]] > 0:
            # add the left child to the stack
            postorder_stack.append(inorder_map[inorder[node]] - 1)

        # if the right child is not None
        if inorder_map[inorder[node]] < len(inorder) - 1:
            # add the right child to the stack
            postorder_stack.append(inorder_map[inorder[node]] + 1)

    return preorder

